style.css:
@-moz-document domain("pinterest.com") {
/* ===== FUNDO GERAL ===== */
  body,
  div[role="main"],
  main,
  [data-test-id="homefeed-container"] {
    background-color: #0f0f14 !important;
  }

  /* ===== BARRA SUPERIOR ===== */
  header,
  header * {
    background-color: #0c0c11 !important;
    color: #f2f2f2 !important;
  }

  /* ===== BARRA LATERAL ===== */
  nav,
  nav * {
    background-color: #0c0c11 !important;
    color: #f2f2f2 !important;
  }

  /* ===== INPUT DE PESQUISA ===== */
  input {
    background-color: #1a1a22 !important;
    color: #ffffff !important;
  }

  input::placeholder {
    color: #bdbdc7 !important;
  }

  /* ===== CARDS / PINS ===== */
  [data-test-id="pin"],
  [data-test-id="pinWrapper"] {
    background-color: #14141b !important;
  }

  /* ===== BOTÕES ===== */
  button,
  a[role="button"] {
    background-color: #f3a8c4 !important;
    color: #2b0f1c !important;
    border-radius: 14px !important;
  }

  /* BOTÃO SALVAR */
  [data-test-id="pin-save-button"] {
    background-color: #f7b7d2 !important;
    color: #2b0f1c !important;
  }

  /* ===== TEXTOS ===== */
  span,
  div,
  p {
    color: #f2f2f2;
  }
}
